// @vitest-environment jsdom
import { fireEvent, render, screen } from "@testing-library/react";
import { Link, MemoryRouter, Route, Routes } from "react-router";
import { describe, expect, it } from "vitest";
import type { GameHistoryEntry } from "../../domain/game/types";
import { InMemoryJsonStore } from "../../infrastructure/persistence/JsonStore";
import { AppProvider } from "../context/AppContext";
import {
	CorruptJsonStore,
	canvas2d,
	createdAudioUrls,
	getFakeLocalStorage,
	makeFixedRoundGame,
	makeGame,
	makeHistoryEntry,
	makeSymbolItem,
	renderWithApp,
} from "../test-utils/renderWithApp";
import { Dashboard } from "./Dashboard";
import { GamePage } from "./GamePage";

const CANVAS_NAME = "Drawing area for writing Thai characters";

function reveal() {
	fireEvent.click(screen.getByRole("button", { name: "Show Answer" }));
}

function rate(label: RegExp) {
	fireEvent.click(screen.getByRole("button", { name: label }));
}

function setCount(value: string) {
	fireEvent.change(screen.getByLabelText("Items per round"), {
		target: { value },
	});
}

function startRound() {
	fireEvent.click(screen.getByRole("button", { name: "Start Round" }));
}

/** A raw `PropertyCard` DTO as it sits inside the persisted SRS blob. */
function scriptCardDTO(character: string) {
	return {
		id: `${character}-recognition`,
		question: `What sound does ${character} make?`,
		correctAnswer: "answer",
		choices: ["answer", "other"],
		srs: {
			easeFactor: 2,
			interval: 10,
			repetitions: 0,
			learningStep: 1,
			nextReviewDate: "2026-01-01T00:00:00.000Z",
			lastReviewDate: null,
			lapseCount: 0,
		},
		symbolCharacter: character,
		property: "recognition",
		lessonNumber: 1,
	};
}

describe("GamePage", () => {
	// AC1
	it("presents exactly the configured number of item screens before the summary", () => {
		renderWithApp(<GamePage />, {}, { symbols: ["ม", "น", "ง", "ย", "ว"] });
		setCount("3");
		startRound();

		let screensTraversed = 0;
		while (
			screen.queryByText("Round Complete") === null &&
			screensTraversed < 10
		) {
			expect(screen.getByText(`${screensTraversed + 1} / 3`)).toBeTruthy();
			reveal();
			rate(/Good/);
			screensTraversed += 1;
		}

		expect(screensTraversed).toBe(3);
		expect(screen.getByText("Round Complete")).toBeTruthy();
	});

	// AC2
	it("renders dictation with audio before reveal and reading with audio only after reveal", () => {
		const dictation = makeSymbolItem("ม", "dictation", {
			audioUrl: "/audio/mo-ma.mp3",
			correctAnswer: "maaw maa",
		});
		const reading = makeSymbolItem("น", "reading", {
			audioUrl: "/audio/no-nu.mp3",
			correctAnswer: "naaw nuu",
		});
		const { game } = makeFixedRoundGame([dictation, reading]);
		renderWithApp(<GamePage />, { game });
		startRound();

		// Dictation: prompt audio is constructed up front, canvas is offered.
		expect(createdAudioUrls()).toContain("/audio/mo-ma.mp3");
		expect(screen.getByRole("img", { name: CANVAS_NAME })).toBeTruthy();
		reveal();
		expect(screen.getByText("maaw maa")).toBeTruthy();
		rate(/Good/);

		// Reading: no audio constructed before its reveal...
		expect(screen.getByText("น")).toBeTruthy();
		expect(createdAudioUrls()).not.toContain("/audio/no-nu.mp3");
		reveal();
		// ...exactly one constructed by the reveal.
		expect(
			createdAudioUrls().filter((url) => url === "/audio/no-nu.mp3"),
		).toHaveLength(1);
		expect(screen.getByText("naaw nuu")).toBeTruthy();
	});

	// AC2 (input-mode half)
	it("dictation in paper mode renders no canvas and taps through to the reveal", () => {
		const { game } = makeFixedRoundGame([makeSymbolItem("ม", "dictation")]);
		renderWithApp(<GamePage />, { game });
		fireEvent.click(screen.getByLabelText("Write on paper"));
		startRound();

		expect(screen.queryByRole("img", { name: CANVAS_NAME })).toBeNull();
		reveal();
		expect(screen.getByRole("button", { name: /Good/ })).toBeTruthy();
	});

	// AC3
	it("shows rating buttons only after reveal and advances on rating", () => {
		const { game } = makeFixedRoundGame([
			makeSymbolItem("ม", "dictation"),
			makeSymbolItem("น", "dictation"),
		]);
		renderWithApp(<GamePage />, { game });
		startRound();

		expect(screen.getByText("1 / 2")).toBeTruthy();
		expect(screen.queryByRole("button", { name: /Again/ })).toBeNull();
		reveal();
		expect(screen.getByRole("button", { name: /Again/ })).toBeTruthy();
		rate(/Good/);

		expect(screen.getByText("2 / 2")).toBeTruthy();
		reveal();
		rate(/Easy/);
		expect(screen.getByText("Round Complete")).toBeTruthy();
	});

	// AC4 — the plan's end-to-end SRS-isolation proof, deliberately NOT using
	// renderWithApp: the real AppProvider (module-level singletons and all)
	// is the wiring a hand-built context double would bypass.
	it("leaves the whole thai-srs-state blob byte-identical after a full round through the real AppProvider", () => {
		const seeded = JSON.stringify({
			completedLessons: [1],
			currentLesson: 2,
			cards: {
				"ม-recognition": scriptCardDTO("ม"),
				"น-recognition": scriptCardDTO("น"),
				"ง-recognition": scriptCardDTO("ง"),
			},
			vocabCards: {},
			grammarCards: {},
			sentenceCards: {},
			// Streak/achievement material lives in these fields — the whole
			// blob must survive, not just card schedules.
			sessionHistory: [
				{
					sessionId: "s-1",
					completedAt: "2026-09-01T10:00:00.000Z",
					type: "review",
					durationMs: 60000,
					totalCards: 5,
					correctCount: 4,
					incorrectCount: 1,
					accuracy: 80,
					newCardsGraduated: 1,
				},
			],
			achievements: ["first-lesson"],
		});
		getFakeLocalStorage().setItem("thai-srs-state", seeded);

		render(
			<AppProvider>
				<MemoryRouter initialEntries={["/game"]}>
					<Routes>
						<Route path="/game" element={<GamePage />} />
					</Routes>
				</MemoryRouter>
			</AppProvider>,
		);

		setCount("3");
		startRound();
		for (const rating of [/Again/, /Good/, /Easy/]) {
			reveal();
			rate(rating);
		}
		expect(screen.getByText("Round Complete")).toBeTruthy();

		// The round itself persisted — to its own key...
		expect(
			getFakeLocalStorage().getItem("thai-srs-game-history"),
		).not.toBeNull();
		// ...while the whole SRS blob is byte-identical.
		expect(getFakeLocalStorage().getItem("thai-srs-state")).toBe(seeded);
	});

	// AC5
	it("renders never-played history as its own message", () => {
		renderWithApp(<GamePage />, {}, { symbols: ["ม"] });
		expect(screen.getByText("No games played yet.")).toBeTruthy();
		expect(screen.queryByText(/history is unavailable/i)).toBeNull();
	});

	// AC5
	it("renders stored history entries as a populated list", () => {
		const historyStore = new InMemoryJsonStore<GameHistoryEntry[]>();
		historyStore.save([makeHistoryEntry({ id: "e1", itemCount: 4 })]);
		const game = makeGame({ symbols: ["ม"], historyStore });
		renderWithApp(<GamePage />, { game });

		expect(screen.getByText("Symbols · 4 items")).toBeTruthy();
		expect(screen.getByText("75%")).toBeTruthy();
		expect(screen.queryByText("No games played yet.")).toBeNull();
		expect(screen.queryByText(/history is unavailable/i)).toBeNull();
	});

	// AC5
	it("renders a corrupt history read as unavailable, never as never-played", () => {
		const game = makeGame({
			symbols: ["ม"],
			historyStore: new CorruptJsonStore<GameHistoryEntry[]>(),
		});
		renderWithApp(<GamePage />, { game });

		expect(screen.getByText(/history is unavailable/i)).toBeTruthy();
		expect(screen.queryByText("No games played yet.")).toBeNull();
	});

	// AC6
	it("disables start and explains when no symbols are eligible", () => {
		renderWithApp(<GamePage />);
		expect(screen.getByText(/No symbols to practice yet/)).toBeTruthy();
		expect(screen.queryByRole("button", { name: "Start Round" })).toBeNull();
	});

	// AC7 — two consecutive same-direction items keep the same component
	// instance (same element type, same position, no key), so React's default
	// reconciliation does not remount: the organism's own id-keyed effect
	// must do the resetting.
	it("resets reveal and canvas across two consecutive dictation items", () => {
		const first = makeSymbolItem("ม", "dictation", {
			audioUrl: "/audio/first.mp3",
		});
		const second = makeSymbolItem("น", "dictation", {
			audioUrl: "/audio/second.mp3",
		});
		const { game } = makeFixedRoundGame([first, second]);
		renderWithApp(<GamePage />, { game });
		startRound();

		reveal();
		expect(screen.getByRole("button", { name: /Again/ })).toBeTruthy();
		canvas2d.clearRect.mockClear();
		rate(/Good/);

		// Second dictation item: unrevealed again, canvas cleared, and the
		// id-keyed effect re-ran (its prompt audio was constructed).
		expect(screen.getByRole("button", { name: "Show Answer" })).toBeTruthy();
		expect(screen.queryByRole("button", { name: /Again/ })).toBeNull();
		expect(canvas2d.clearRect).toHaveBeenCalled();
		expect(createdAudioUrls()).toContain("/audio/second.mp3");
	});

	// AC7
	it("resets reveal across two consecutive reading items", () => {
		const { game } = makeFixedRoundGame([
			makeSymbolItem("ม", "reading"),
			makeSymbolItem("น", "reading"),
		]);
		renderWithApp(<GamePage />, { game });
		startRound();

		reveal();
		expect(screen.getByRole("button", { name: /Again/ })).toBeTruthy();
		rate(/Good/);

		expect(screen.getByRole("button", { name: "Show Answer" })).toBeTruthy();
		expect(screen.queryByRole("button", { name: /Again/ })).toBeNull();
	});

	// AC8
	it("keeps start unavailable for zero, negative, and non-integer item counts", () => {
		renderWithApp(<GamePage />, {}, { symbols: ["ม", "น", "ง"] });
		const start = screen.getByRole("button", {
			name: "Start Round",
		}) as HTMLButtonElement;

		for (const bad of ["0", "-2", "2.5", "", "99"]) {
			setCount(bad);
			expect(start.disabled).toBe(true);
		}

		setCount("2");
		expect(start.disabled).toBe(false);
	});

	// AC9 — jsdom's default (no md: desktop viewport) is exactly the mobile
	// case: the Dashboard card must be reachable without the desktop nav.
	it("dashboard shows a game quick-action card that navigates to /game", () => {
		renderWithApp(
			<Routes>
				<Route path="/" element={<Dashboard />} />
				<Route path="/game" element={<GamePage />} />
			</Routes>,
		);

		expect(screen.getByText("Game")).toBeTruthy();
		fireEvent.click(screen.getByText("Practice round"));
		expect(screen.getByText("Practice Game")).toBeTruthy();
	});

	// AC10
	it("abandoning a round persists nothing and the next round starts clean", () => {
		const { game, historyStore } = makeFixedRoundGame([
			makeSymbolItem("ม", "reading"),
			makeSymbolItem("น", "reading"),
		]);
		renderWithApp(
			<Routes>
				<Route
					path="/"
					element={
						<div>
							Dashboard home
							<Link to="/game">back to game</Link>
						</div>
					}
				/>
				<Route path="/game" element={<GamePage />} />
			</Routes>,
			{ game },
			{ route: "/game" },
		);

		// Start (default count 2), rate one item, abandon mid-round.
		startRound();
		reveal();
		rate(/Again/);
		fireEvent.click(screen.getByRole("button", { name: "End round" }));
		expect(screen.getByText("Dashboard home")).toBeTruthy();
		expect(historyStore.load()).toEqual({ status: "empty" });

		// Returning shows setup, with no history entry from the abandoned round.
		fireEvent.click(screen.getByText("back to game"));
		expect(screen.getByText("Practice Game")).toBeTruthy();
		expect(screen.getByText("No games played yet.")).toBeTruthy();

		// A fresh round tallies only its own ratings.
		startRound();
		reveal();
		rate(/Good/);
		reveal();
		rate(/Good/);
		expect(screen.getByText("2 of 2 items rated")).toBeTruthy();
		expect(screen.getByText("100%")).toBeTruthy();
		expect(screen.getByText("Again").parentElement?.textContent).toBe("0Again");

		const persisted = historyStore.load();
		expect(persisted.status).toBe("ok");
		if (persisted.status === "ok") {
			expect(persisted.value).toHaveLength(1);
		}
	});

	// AC11
	it("labels the count input and input-mode toggle and keeps them keyboard-operable", () => {
		renderWithApp(<GamePage />, {}, { symbols: ["ม", "น"] });

		const count = screen.getByLabelText("Items per round") as HTMLInputElement;
		count.focus();
		expect(document.activeElement).toBe(count);
		fireEvent.change(count, { target: { value: "1" } });
		expect(count.value).toBe("1");

		const draw = screen.getByLabelText("Draw on canvas") as HTMLInputElement;
		const paper = screen.getByLabelText("Write on paper") as HTMLInputElement;
		expect(draw.checked).toBe(true);
		paper.focus();
		expect(document.activeElement).toBe(paper);
		// jsdom cannot synthesize the browser's Space-key default action on a
		// focused radio; activating the focused element is its stand-in.
		fireEvent.click(paper);
		expect(paper.checked).toBe(true);
		expect(draw.checked).toBe(false);
	});
});

/**
 * Page-level render-test harness — the first in this repository.
 *
 * Importing this module registers the environment repairs every page-level
 * render test needs and that no global vitest config provides (see
 * CONTEXT.md):
 *
 * - an explicit `afterEach(cleanup)` — there is no `globals: true` /
 *   `setupFiles`, so Testing-Library's auto-cleanup never registers;
 * - a hand-built `localStorage` on `globalThis` — jsdom under vitest 4 in
 *   this repo leaves it undefined (Node's own experimental global
 *   conflicts), so tests stub a Storage-shaped fake instead;
 * - a stubbed `Audio` constructor that records constructed URLs (jsdom's
 *   `HTMLMediaElement.play` throws synchronously) plus prototype stubs for
 *   `play`/`pause` for any real media element;
 * - a stubbed `HTMLCanvasElement.getContext` returning a shared recording
 *   2D context (jsdom has none without the `canvas` package), which also
 *   lets tests observe `clearRect` calls.
 *
 * Test files still need their own `// @vitest-environment jsdom` docblock —
 * the pragma only works in the test file itself.
 */
import { cleanup, type RenderResult, render } from "@testing-library/react";
import type { ReactElement } from "react";
import { MemoryRouter } from "react-router";
import { afterEach, beforeEach, vi } from "vitest";
import { ConductReviewUseCase } from "../../application/use-cases/ConductReviewUseCase";
import { ManageDataUseCase } from "../../application/use-cases/ManageDataUseCase";
import { ManageItemsUseCase } from "../../application/use-cases/ManageItemsUseCase";
import { PlayGameUseCase } from "../../application/use-cases/PlayGameUseCase";
import { QueryDashboardUseCase } from "../../application/use-cases/QueryDashboardUseCase";
import { StartLessonUseCase } from "../../application/use-cases/StartLessonUseCase";
import type { GameHistoryRepository } from "../../domain/game/ports/GameHistoryRepository";
import { GameItemSelectionService } from "../../domain/game/services/GameItemSelectionService";
import { SymbolGameItemSource } from "../../domain/game/services/SymbolGameItemSource";
import { normalizeRequestedCount } from "../../domain/game/services/sampling";
import type {
	GameChallengeDirection,
	GameHistoryEntry,
	GameItem,
	GameRoundConfig,
	SymbolItemContent,
} from "../../domain/game/types";
import grammarData from "../../domain/grammar/data/grammar.json";
import { GrammarService } from "../../domain/grammar/services/GrammarLessonService";
import type { GrammarEntry } from "../../domain/grammar/types";
import { ScriptPropertyCard } from "../../domain/script/entities/ScriptPropertyCard";
import { LearningService } from "../../domain/script/services/ScriptLessonService";
import sentenceData from "../../domain/sentence/data/sentences.json";
import { SentenceService } from "../../domain/sentence/services/SentenceLessonService";
import type { SentenceEntry } from "../../domain/sentence/types";
import { ReviewService } from "../../domain/session/services/ReviewService";
import { ApprenticeService } from "../../domain/shared/services/ApprenticeService";
import { LeechService } from "../../domain/shared/services/LeechService";
import vocabularyData from "../../domain/vocabulary/data/vocabulary.json";
import { VocabularyService } from "../../domain/vocabulary/services/VocabularyLessonService";
import type { VocabEntry } from "../../domain/vocabulary/types";
import { NotificationScheduler } from "../../infrastructure/notifications/NotificationScheduler";
import {
	InMemoryJsonStore,
	type JsonStore,
	type JsonStoreLoadResult,
	type JsonStoreSaveResult,
} from "../../infrastructure/persistence/JsonStore";
import { InMemoryStorage } from "../../infrastructure/persistence/Storage";
import { StorageCardRepository } from "../../infrastructure/persistence/StorageCardRepository";
import { StorageGameHistoryRepository } from "../../infrastructure/persistence/StorageGameHistoryRepository";
import { StorageLearnerStateRepository } from "../../infrastructure/persistence/StorageLearnerStateRepository";
import { AppContext, type AppContextValue } from "../context/AppContext";

// --- localStorage fake (jsdom's own is unreliable here, see module docs) ---

export class FakeLocalStorage implements Storage {
	private store = new Map<string, string>();

	get length(): number {
		return this.store.size;
	}

	clear(): void {
		this.store.clear();
	}

	getItem(key: string): string | null {
		return this.store.has(key) ? (this.store.get(key) as string) : null;
	}

	key(index: number): string | null {
		return Array.from(this.store.keys())[index] ?? null;
	}

	removeItem(key: string): void {
		this.store.delete(key);
	}

	setItem(key: string, value: string): void {
		this.store.set(key, value);
	}
}

let fakeLocalStorage = new FakeLocalStorage();

/** The per-test `localStorage` stand-in installed on `globalThis`. */
export function getFakeLocalStorage(): FakeLocalStorage {
	return fakeLocalStorage;
}

// --- Audio stub (jsdom throws synchronously from `play()`) ---

export class StubAudio {
	static createdUrls: string[] = [];
	currentTime = 0;

	constructor(readonly src?: string) {
		StubAudio.createdUrls.push(src ?? "");
	}

	play(): Promise<void> {
		return Promise.resolve();
	}

	pause(): void {}
}

/** URLs passed to `new Audio(url)` since the current test began. */
export function createdAudioUrls(): readonly string[] {
	return StubAudio.createdUrls;
}

// --- Canvas 2D stub (jsdom has no 2D context without the canvas package) ---

export const canvas2d = {
	clearRect: vi.fn(),
	beginPath: vi.fn(),
	moveTo: vi.fn(),
	lineTo: vi.fn(),
	stroke: vi.fn(),
	lineCap: "round",
	lineJoin: "round",
	lineWidth: 4,
	strokeStyle: "",
};

beforeEach(() => {
	fakeLocalStorage = new FakeLocalStorage();
	globalThis.localStorage = fakeLocalStorage;
	globalThis.Audio = StubAudio as unknown as typeof Audio;
	StubAudio.createdUrls = [];
	canvas2d.clearRect.mockClear();
	canvas2d.beginPath.mockClear();
	canvas2d.moveTo.mockClear();
	canvas2d.lineTo.mockClear();
	canvas2d.stroke.mockClear();
	if (typeof HTMLMediaElement !== "undefined") {
		HTMLMediaElement.prototype.play = () => Promise.resolve();
		HTMLMediaElement.prototype.pause = () => {};
	}
	if (typeof HTMLCanvasElement !== "undefined") {
		HTMLCanvasElement.prototype.getContext = (() =>
			canvas2d) as unknown as HTMLCanvasElement["getContext"];
	}
});

afterEach(() => {
	cleanup();
	Reflect.deleteProperty(globalThis, "localStorage");
});

// --- Fixtures ---

const DEFAULT_SRS = {
	easeFactor: 2.0,
	interval: 10,
	repetitions: 0,
	learningStep: 1,
	nextReviewDate: "2026-01-01T00:00:00.000Z",
	lastReviewDate: null,
	lapseCount: 0,
};

/**
 * One script card for `symbolCharacter` — enough to make that symbol
 * eligible (eligibility is card-driven; content still comes from
 * `symbols.ts`, so pass characters that exist there, e.g. "ม", "น", "ง").
 */
export function makeScriptCard(symbolCharacter: string): ScriptPropertyCard {
	return ScriptPropertyCard.fromDTO({
		id: `${symbolCharacter}-recognition`,
		question: `What sound does ${symbolCharacter} make?`,
		correctAnswer: "answer",
		choices: ["answer", "other"],
		srs: { ...DEFAULT_SRS },
		symbolCharacter,
		property: "recognition",
		lessonNumber: 1,
	});
}

/** A `GameItem` with a pre-assigned direction, for fixed-round tests. */
export function makeSymbolItem(
	symbolCharacter: string,
	challengeDirection: GameChallengeDirection,
	overrides: Partial<Omit<SymbolItemContent, "kind">> = {},
): GameItem {
	return {
		kind: "symbol",
		symbolCharacter,
		promptText: symbolCharacter,
		correctAnswer: `${symbolCharacter} name`,
		audioUrl: `/audio/${symbolCharacter}.mp3`,
		...overrides,
		challengeDirection,
	};
}

/** A persisted history entry, for seeding history stores. */
export function makeHistoryEntry(
	overrides: Partial<GameHistoryEntry> = {},
): GameHistoryEntry {
	return {
		id: "entry-1",
		playedAt: "2026-09-01T10:00:00.000Z",
		pools: ["script"],
		itemCount: 4,
		summary: {
			ratingCounts: { 1: 0, 2: 1, 3: 0, 4: 2, 5: 1 },
			ratedCount: 4,
			accuracy: 75,
		},
		...overrides,
	};
}

/** A `JsonStore` whose every load reports corrupt — the unavailable case. */
export class CorruptJsonStore<T> implements JsonStore<T> {
	load(): JsonStoreLoadResult<T> {
		return { status: "corrupt" };
	}

	save(): JsonStoreSaveResult {
		return { status: "ok" };
	}
}

// --- Game use-case factories ---

export interface MakeGameOptions {
	symbols?: readonly string[];
	historyStore?: JsonStore<GameHistoryEntry[]>;
}

/** A real `PlayGameUseCase` over in-memory persistence. */
export function makeGame(options: MakeGameOptions = {}): PlayGameUseCase {
	const cardRepo = new StorageCardRepository(new InMemoryStorage());
	cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
	return new PlayGameUseCase(
		new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
		new StorageGameHistoryRepository(
			options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>(),
		),
	);
}

class FixedRoundGame extends PlayGameUseCase {
	constructor(
		private readonly fixedItems: readonly GameItem[],
		selection: GameItemSelectionService,
		historyRepository: GameHistoryRepository,
	) {
		super(selection, historyRepository);
	}

	override startRound(config: GameRoundConfig): GameItem[] {
		return this.fixedItems.slice(
			0,
			normalizeRequestedCount(config.itemCount, this.fixedItems.length),
		);
	}
}

/**
 * A `PlayGameUseCase` whose rounds are exactly `items`, in order, with the
 * directions the test pre-assigned — everything else (rating, finishing,
 * history) stays real.
 */
export function makeFixedRoundGame(
	items: readonly GameItem[],
	options: Pick<MakeGameOptions, "historyStore"> = {},
): { game: PlayGameUseCase; historyStore: JsonStore<GameHistoryEntry[]> } {
	const historyStore =
		options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>();
	const cardRepo = new StorageCardRepository(new InMemoryStorage());
	const game = new FixedRoundGame(
		items,
		new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
		new StorageGameHistoryRepository(historyStore),
	);
	return { game, historyStore };
}

// --- The harness itself ---

export interface AppHarness {
	value: AppContextValue;
	storage: InMemoryStorage;
	cardRepo: StorageCardRepository;
	historyStore: InMemoryJsonStore<GameHistoryEntry[]>;
	game: PlayGameUseCase;
}

export interface MakeAppValueOptions {
	/** Characters (existing in `symbols.ts`) to seed one script card each for. */
	symbols?: readonly string[];
}

/**
 * A complete in-memory `AppContextValue`: every use case and service the
 * real `AppContext.tsx` wires, built over `InMemoryStorage` instead of
 * `localStorage`, plus a real `PlayGameUseCase` over an in-memory history
 * store.
 */
export function makeAppValue(options: MakeAppValueOptions = {}): AppHarness {
	const storage = new InMemoryStorage();
	const cardRepo = new StorageCardRepository(storage);
	const stateRepo = new StorageLearnerStateRepository(storage);
	const apprenticeService = new ApprenticeService(cardRepo);
	const leechService = new LeechService(cardRepo);
	const learningService = new LearningService(
		cardRepo,
		stateRepo,
		apprenticeService,
	);
	const reviewService = new ReviewService(cardRepo, stateRepo);
	const vocabularyService = new VocabularyService(
		cardRepo,
		stateRepo,
		vocabularyData as VocabEntry[],
	);
	const grammarService = new GrammarService(
		cardRepo,
		grammarData as unknown as GrammarEntry[],
		apprenticeService,
		vocabularyData as VocabEntry[],
	);
	const sentenceService = new SentenceService(
		cardRepo,
		sentenceData as unknown as SentenceEntry[],
		vocabularyService,
		apprenticeService,
	);

	cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));

	const historyStore = new InMemoryJsonStore<GameHistoryEntry[]>();
	const game = new PlayGameUseCase(
		new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
		new StorageGameHistoryRepository(historyStore),
	);

	const value: AppContextValue = {
		state: storage.load(),
		refresh: () => {},
		lesson: new StartLessonUseCase(
			learningService,
			vocabularyService,
			grammarService,
			sentenceService,
		),
		review: new ConductReviewUseCase(
			reviewService,
			new NotificationScheduler(),
		),
		dashboard: new QueryDashboardUseCase(
			cardRepo,
			apprenticeService,
			leechService,
		),
		data: new ManageDataUseCase(stateRepo),
		items: new ManageItemsUseCase(cardRepo),
		vocab: vocabularyService,
		checkAchievements: () => [],
		game,
	};

	return { value, storage, cardRepo, historyStore, game };
}

export interface RenderWithAppOptions extends MakeAppValueOptions {
	/** Initial router entry, default `/`. */
	route?: string;
}

/**
 * Renders `ui` inside `<AppContext.Provider>` (a fresh in-memory
 * `AppContextValue`, with `overrides` merged in) and a `MemoryRouter`.
 * Returns Testing-Library's render result plus the harness internals.
 */
export function renderWithApp(
	ui: ReactElement,
	overrides: Partial<AppContextValue> = {},
	options: RenderWithAppOptions = {},
): RenderResult & { app: AppHarness } {
	const app = makeAppValue({ symbols: options.symbols });
	const value: AppContextValue = { ...app.value, ...overrides };
	const result = render(
		<AppContext.Provider value={value}>
			<MemoryRouter initialEntries={[options.route ?? "/"]}>{ui}</MemoryRouter>
		</AppContext.Provider>,
	);
	return Object.assign(result, { app: { ...app, value, game: value.game } });
}

